import{_ as e,o,c as i,a2 as t}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 1","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-III/Lectura_Catedra_Evaluacion_1.md","filePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-III/Lectura_Catedra_Evaluacion_1.md"}'),r={name:"materias/Proyecto_Sociotecnologico_I/documentacion/I-III/Lectura_Catedra_Evaluacion_1.md"};function n(s,a,l,c,d,u){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="manual-de-estudio-profundo-evaluacion-1" tabindex="-1">Manual de Estudio Profundo: Evaluación 1 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-1" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 1&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-trayecto-i" tabindex="-1">Materia: Proyecto Sociotecnológico (Trayecto I) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-trayecto-i" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico (Trayecto I)&quot;">​</a></h2><h3 id="eje-tematico-ejecucion-del-plan-de-accion-manos-a-la-obra" tabindex="-1">Eje Temático: Ejecución del Plan de Acción (Manos a la Obra) <a class="header-anchor" href="#eje-tematico-ejecucion-del-plan-de-accion-manos-a-la-obra" aria-label="Permalink to &quot;Eje Temático: Ejecución del Plan de Acción (Manos a la Obra)&quot;">​</a></h3><hr><h2 id="🧭-introduccion-de-la-tinta-a-los-circuitos" tabindex="-1">🧭 Introducción: De la Tinta a los Circuitos <a class="header-anchor" href="#🧭-introduccion-de-la-tinta-a-los-circuitos" aria-label="Permalink to &quot;🧭 Introducción: De la Tinta a los Circuitos&quot;">​</a></h2><p>Han pasado dos trimestres planificando. Hicieron abordaje comunitario, aplicaron encuestas, dibujaron árboles y estructuraron un cronograma de Gantt impecable. Todo se ve perfecto en papel. Pero en la informática real, los componentes fallan, las fuentes de poder estallan y los usuarios hacen clic donde no deben.</p><p>El <strong>Trimestre I-III</strong> es la prueba de fuego: es el momento de ejecutar. Es aquí donde la &quot;Informática Aplicada&quot; cobra vida y los tornillos comienzan a girar.</p><hr><h2 id="🏛️-capitulo-i-el-arte-de-ejecutar" tabindex="-1">🏛️ CAPÍTULO I: El Arte de Ejecutar <a class="header-anchor" href="#🏛️-capitulo-i-el-arte-de-ejecutar" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: El Arte de Ejecutar&quot;">​</a></h2><p>Ejecutar no es entrar a la sala de computación a desarmar cosas a ciegas. Es seguir estricta y cronológicamente las actividades que ustedes mismos pautaron en su <strong>Estructura Analítica del Proyecto (EAP)</strong>.</p><h3 id="_1-1-el-respeto-al-cronograma" tabindex="-1">1.1 El Respeto al Cronograma <a class="header-anchor" href="#_1-1-el-respeto-al-cronograma" aria-label="Permalink to &quot;1.1 El Respeto al Cronograma&quot;">​</a></h3><p>Si su Gantt indicaba que la semana 1 era para <em>Soplado y Limpieza Física</em>, no pueden instalar software operativo esa semana. La disciplina metodológica es un pilar evaluado por sus tutores. Todo desvío del cronograma debe estar justificado.</p><h3 id="_1-2-protocolos-de-soporte-tecnico-comunitario" tabindex="-1">1.2 Protocolos de Soporte Técnico Comunitario <a class="header-anchor" href="#_1-2-protocolos-de-soporte-tecnico-comunitario" aria-label="Permalink to &quot;1.2 Protocolos de Soporte Técnico Comunitario&quot;">​</a></h3><p>Cuando se interviene hardware que no es propiedad de la universidad sino de una escuela o ambulatorio, deben seguir protocolos rigurosos:</p><ol><li><strong>Fotografía del &quot;Antes&quot;:</strong> Documenten el estado exacto en el que encontraron cada equipo (cables desconectados, polvo, pantallas rotas). Esto es vital para su Informe Final.</li><li><strong>Etiquetado:</strong> Nunca desarmen 5 computadoras a la vez sin etiquetar de dónde salió cada memoria RAM o cada disco duro. Usen cinta adhesiva.</li><li><strong>Manejo Antiestático:</strong> Utilicen guantes o toquen el chasis antes de manipular las tarjetas madre. No conviertan un mantenimiento en una catástrofe.</li></ol><hr><h2 id="🧩-capitulo-ii-la-bitacora-de-campo" tabindex="-1">🧩 CAPÍTULO II: La Bitácora de Campo <a class="header-anchor" href="#🧩-capitulo-ii-la-bitacora-de-campo" aria-label="Permalink to &quot;🧩 CAPÍTULO II: La Bitácora de Campo&quot;">​</a></h2><p>El peor enemigo de un investigador es su propia memoria. No confíes en que recordarás dentro de un mes que la &quot;PC número 3&quot; tenía el disco duro dañado.</p><h3 id="_2-1-el-cuaderno-de-novedades" tabindex="-1">2.1 El Cuaderno de Novedades <a class="header-anchor" href="#_2-1-el-cuaderno-de-novedades" aria-label="Permalink to &quot;2.1 El Cuaderno de Novedades&quot;">​</a></h3><p>Cada vez que el equipo vaya a la comunidad a ejecutar una tarea, un estudiante debe estar designado como el <em>Secretario de Campo</em>. Su función es registrar:</p><ul><li><strong>Fecha y Hora:</strong> Cuándo llegaron y cuándo se fueron.</li><li><strong>Actividad Realizada:</strong> Ej. &quot;Mantenimiento preventivo de 4 estaciones de trabajo&quot;.</li><li><strong>Novedades/Contratiempos:</strong> Ej. &quot;El liceo estaba sin electricidad, la actividad tuvo que posponerse&quot;.</li><li><strong>Firmas:</strong> Al terminar la jornada, el enlace comunitario (el director, el jefe del consejo comunal) <strong>debe firmar</strong> la bitácora validando que ustedes realmente trabajaron.</li></ul><h3 id="_2-2-evidencia-audiovisual-fotos-y-videos" tabindex="-1">2.2 Evidencia Audiovisual (Fotos y Videos) <a class="header-anchor" href="#_2-2-evidencia-audiovisual-fotos-y-videos" aria-label="Permalink to &quot;2.2 Evidencia Audiovisual (Fotos y Videos)&quot;">​</a></h3><p>Toda ejecución debe estar documentada en fotografías (sin violar la privacidad de las personas). Mostrar una foto de ustedes limpiando un gabinete es una &quot;prueba irrefutable&quot; ante el jurado de la UPSIT de que el trabajo manual existió y no fue mandado a hacer.</p><hr><h2 id="🏗️-capitulo-iii-ejecucion-de-la-alfabetizacion" tabindex="-1">🏗️ CAPÍTULO III: Ejecución de la Alfabetización <a class="header-anchor" href="#🏗️-capitulo-iii-ejecucion-de-la-alfabetizacion" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: Ejecución de la Alfabetización&quot;">​</a></h2><p>Recuerden que el perfil de Trayecto I exige <strong>Soporte a Usuarios</strong>. De nada sirve dejar 10 computadoras perfectas con Canaima GNU/Linux si las secretarias del liceo solo saben usar Windows XP.</p><h3 id="_3-1-los-talleres-de-formacion" tabindex="-1">3.1 Los Talleres de Formación <a class="header-anchor" href="#_3-1-los-talleres-de-formacion" aria-label="Permalink to &quot;3.1 Los Talleres de Formación&quot;">​</a></h3><ul><li><strong>Material de Apoyo:</strong> Entreguen guías impresas (trípticos o manuales de 2 hojas). Si la luz se va, el usuario todavía puede leer qué es LibreOffice.</li><li><strong>Paciencia Pedagógica:</strong> Asuman que el usuario tiene nivel &quot;Cero&quot;. Usen lenguaje claro, eviten tecnicismos innecesarios (no les hablen del &quot;kernel&quot; de Linux, háblenles del &quot;sistema principal&quot;).</li></ul><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p><strong>El Principio del Daño Nulo</strong> Si por inexperiencia ustedes dañan un equipo de la comunidad de forma irreversible durante el soporte técnico, su proyecto corre riesgo de reprobación inmediata. Ante la duda técnica profunda, deténganse y consulten a su tutor técnico institucional.</p></div><p>Una vez que el hardware está limpio, el software instalado y el personal capacitado, ¿Cómo sabemos que hicimos un buen trabajo? Lo descubriremos en la siguiente evaluación: <strong>El Monitoreo y Control</strong>.</p>',30)])])}const h=e(r,[["render",n]]);export{p as __pageData,h as default};
